import{_ as p,a0 as o,w as n,s as i,I as r,x as t,a1 as s,A as a,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Ryver：你应该使用它替代 Slack | LCTT x X-CMD","titleTemplate":false,"description":"Ryver：你应该使用它替代 Slack | LCTT (201610) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ryver：你应该使用它替代 Slack | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ryver：你应该使用它替代 Slack | LCTT (201610) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201610/20160913 Ryver -  Why You Should Be Using It instead of Slack","title":"Ryver：你应该使用它替代 Slack","tag":"201610","desc":""},"relativePath":"201610/20160913 Ryver -  Why You Should Be Using It instead of Slack.md","filePath":"[post].md"}'),m={name:"201610/20160913 Ryver -  Why You Should Be Using It instead of Slack.md"};function y(k,e,u,v,f,S){const l=o("Link");return n(),i("div",null,[e[19]||(e[19]=r("h1",{id:"ryver-你应该使用它替代-slack",tabindex:"-1"},[t("Ryver：你应该使用它替代 Slack "),r("a",{class:"header-anchor",href:"#ryver-你应该使用它替代-slack","aria-label":"Permalink to “Ryver：你应该使用它替代 Slack”"},"​")],-1)),e[20]||(e[20]=r("p",null,[r("img",{src:"https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/09/Ryver-Slack-Feature.jpg",alt:""})],-1)),r("p",null,[e[1]||(e[1]=t("貌似每个人都听说过 ",-1)),s(l,{href:"https://www.maketecheasier.com/new-slack-features/"},{default:a(()=>[...e[0]||(e[0]=[t("Slack",-1)])]),_:1}),e[2]||(e[2]=t("，它是一款跨平台的，可以使你时刻保持与他人同步的团队沟通应用。它革新了用户讨论和规划项目的方式，显而易见，它升级了 email 的沟通功能。",-1))]),e[21]||(e[21]=d('<p>我在一个非常小的写作团队工作，不管是通过手机还是电脑，我从未在使用 Slack 过程中遇到过沟通问题。若想与任何规模的团队保持同步，继续使用 Slack 仍然不失为不错的方式。</p><p>既然如此，为什么我们还要讨论今天的话题？Ryver 被人们认为是下一个热点，相比 Slack，Ryver 提供了升级版的服务。Ryver 完全免费，它的团队正在奋力争取更大的市场份额。</p><p>是否 Ryver 已经强大到可以扮演 Slack 杀手的角色？这两种旗鼓相当的消息应用究竟有何不同？</p><p>欲知详情，请阅读下文。</p><h3 id="为什么用-ryver" tabindex="-1">为什么用 Ryver ? <a class="header-anchor" href="#为什么用-ryver" aria-label="Permalink to “为什么用 Ryver ?”">​</a></h3><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/04/Ryver.jpg" alt=""></p><p>既然 Slack 能用为什么还要折腾呢？Ryver 的开发者对 Slack 的功能滚瓜烂熟，他们希望 Ryver 改进的服务足以让你移情别恋。他们承诺 Ryver 提供完全免费的团队沟通服务，并且不会在任何一个环节隐形收费。</p><p>谢天谢地，他们用高质量产品兑现了自己的承诺。</p><p>额外的内容是关键所在，他们承诺去掉一些你在 Slack 免费账号上面遇到的限制。无限的存储空间是一个加分点，除此之外，在许多其他方面 Ryver 也更加开放。如果存储空间限制对你来说是个痛点，不防试试 Ryver。</p><p>这是一个简单易用的系统，所有的功能都可以一键搞定。这种设计哲学使 Apple 大获成功。当你开始使用它之后，也不会遭遇成长的烦恼。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/09/ryver-web-interface.png" alt=""></p><p>会话分为私聊和公示，这意味着团队平台和私人用途有明确的界限。它应该有助于避免将任何尴尬的广而告之给你的同事，这些问题我在使用 Slack 期间都遇到过。</p><p>Ryver 支持与大量现成的 App 的集成，并在大多数平台上有原生应用程序。</p><p>在需要时，你可以添加访客而无需增加费用，如果你经常和外部客户打交道，这将是一个非常有用的功能。访客可以增加更多的访客，这种流动性的元素是无法从其他更流行的消息应用中看到的。</p><p>考虑到 Ryver 是一个为迎合不同需求而产生的完全不同的服务。如果你需要一个账户来处理几个客户，Ryver 值得一试。</p>',15)),r("p",null,[e[4]||(e[4]=t("问题是它是如何做到免费的呢？ 简单的答案是高级用户将为你的使用付了费。 就像 Spotify 和其他应用一样，有一小部分人为我们其他人支付了费用。 这里有一个",-1)),s(l,{href:"http://www.ryver.com/downloads/"},{default:a(()=>[...e[3]||(e[3]=[t("直接链接",-1)])]),_:1}),e[5]||(e[5]=t("到他们的下载页面的地址，如果有兴趣就去试一试吧。",-1))]),e[22]||(e[22]=r("h3",{id:"你应该切换到-ryver-吗",tabindex:"-1"},[t("你应该切换到 Ryver 吗？ "),r("a",{class:"header-anchor",href:"#你应该切换到-ryver-吗","aria-label":"Permalink to “你应该切换到 Ryver 吗？”"},"​")],-1)),e[23]||(e[23]=r("p",null,[r("img",{src:"https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/04/Slack-homepage.jpg",alt:""})],-1)),e[24]||(e[24]=r("p",null,"像我一样在小团队使用 Slack 的体验还是非常棒，但是 Ryver 可以给予的更多。一个完全免费的团队沟通应用的想法不可谓不宏伟，更何况它工作的十分完美。",-1)),e[25]||(e[25]=r("p",null,"同时使用这两种消息应用也无可厚非，但是如果你不愿意为一个白金 Slack 账户付费，一定要尝试一下竞争对手的服务。你可能会发现，两者各擅胜场，这取决于你需要什么。",-1)),e[26]||(e[26]=r("p",null,"最重要的是，Ryver 是一个极棒的免费替代品，它不仅仅是一个 Slack 克隆。他们清楚地知道他们想要实现什么，他们有一个可以在拥挤不堪的市场提供不同的东西的不错的产品。",-1)),e[27]||(e[27]=r("p",null,"但是，如果将来持续缺乏资金，Ryver 有可能消失。 它可能会让你的团队和讨论陷入混乱。 目前一切还好，但是如果你计划把更大的业务委托给这个新贵还是需要三思而行。",-1)),e[28]||(e[28]=r("p",null,"如果你厌倦了 Slack 对免费帐户的限制，你会对 Ryver 印象深刻。 要了解更多，请访问其网站以获取有关服务的信息。",-1)),e[29]||(e[29]=r("hr",null,null,-1)),r("p",null,[e[7]||(e[7]=t("via: ",-1)),s(l,{href:"https://www.maketecheasier.com/why-use-ryver-instead-of-slack/"},{default:a(()=>[...e[6]||(e[6]=[t("https://www.maketecheasier.com/why-use-ryver-instead-of-slack/",-1)])]),_:1})]),r("p",null,[e[11]||(e[11]=t("作者：",-1)),s(l,{href:"https://www.maketecheasier.com/author/james-ashmore/"},{default:a(()=>[...e[8]||(e[8]=[t("James Milin-Ashmore",-1)])]),_:1}),e[12]||(e[12]=t(" 译者：",-1)),s(l,{href:"https://github.com/firstadream"},{default:a(()=>[...e[9]||(e[9]=[t("firstadream",-1)])]),_:1}),e[13]||(e[13]=t(" 校对：",-1)),s(l,{href:"https://github.com/wxy"},{default:a(()=>[...e[10]||(e[10]=[t("wxy",-1)])]),_:1})]),r("p",null,[e[16]||(e[16]=t("本文由 ",-1)),s(l,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[14]||(e[14]=[t("LCTT",-1)])]),_:1}),e[17]||(e[17]=t(" 原创编译，",-1)),s(l,{href:"https://linux.cn/"},{default:a(()=>[...e[15]||(e[15]=[t("Linux中国",-1)])]),_:1}),e[18]||(e[18]=t(" 荣誉推出",-1))])])}const g=p(m,[["render",y]]);export{T as __pageData,g as default};
